const CACHE='lanyang-quest-v14';
const FILES=['./','index.html','styles.css','v2.css?v=14','game.js?v=14','manifest.webmanifest','assets/legend-opening.png','assets/quest-guides.png','assets/quest-map-lanyang-v2.png','assets/certificate-glory-v2.png','assets/lanyang-museum-photo.png','assets/plain-floor-map.png','assets/plain-objects-sprite.png','assets/wetland-residents-sprite.png','assets/yilan-treasures-sprite.png','assets/guishan-emblem.png','assets/rpg-scene-01-architecture-v2.jpg','assets/rpg-scene-02-mist-forest-v1.jpg','assets/rpg-scene-03-forest-council-v1.jpg','assets/rpg-scene-04-river-archive-v1.jpg','assets/rpg-scene-05-kuroshio-v1.jpg','assets/rpg-scene-06-nanfeng-v1.jpg'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',e=>{if(e.request.method==='GET')e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(res=>{const copy=res.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));return res}).catch(()=>caches.match('index.html'))))});
